function Send-SyslogMessage {
 param([string]$SyslogServer, [string]$Message, [int]$Severity=6, [int]$Port=$SyslogPort)
 $pri = (1*8)+$Severity # Facility=user(1)
 $ts = Get-Date -Format 'MMM dd HH:mm:ss'
 $hostname = $env:COMPUTERNAME
 $payload = "<$pri>$ts $hostname PowerShell: $Message"
 $bytes = [System.Text.Encoding]::ASCII.GetBytes($payload)
 $udp = New-Object System.Net.Sockets.UdpClient
 try { $udp.Send($bytes, $bytes.Length, $SyslogServer, $Port) | Out-Null } finally { $udp.Dispose() }
}

function New-ScheduledTaskDSI {
