 Invoke-Command -ComputerName $ComputerName -ScriptBlock {
 param($tn,$sp,$tt,$trtime,$ru)
 $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument "-NonInteractive -NoProfile -File `"$sp`""
 $trigger = switch($tt) {
 'Daily' { New-ScheduledTaskTrigger -Daily -At $trtime }
 'Weekly' { New-ScheduledTaskTrigger -Weekly -DaysOfWeek Monday -At $trtime }
 'Startup' { New-ScheduledTaskTrigger -AtStartup }
 'AtLogon' { New-ScheduledTaskTrigger -AtLogOn }
 'Once' { New-ScheduledTaskTrigger -Once -At (Get-Date $trtime) }
 }
 $settings = New-ScheduledTaskSettingsSet -RunOnlyIfNetworkAvailable:$false -StartWhenAvailable -MultipleInstances IgnoreNew
 Register-ScheduledTask -TaskName $tn -Action $action -Trigger $trigger -Settings $settings -RunLevel Highest -User $ru -Force
 } -ArgumentList $TaskName,$ScriptPath,$TriggerType,$TriggerTime,$RunAsUser
 Write-SysLog "Tâche planifiée créée : '$TaskName' ($TriggerType @ $TriggerTime) sur $ComputerName"
