function Invoke-SQLQuery {
 param([string]$Query,[string]$Database,[string]$Server=$SQLServer,[PSCredential]$Credential=$null)
 $connStr = "Server=$Server;Database=$Database;"
 if ($Credential) { $connStr += "User Id=$($Credential.UserName);Password=$($Credential.GetNetworkCredential().Password);" } else { $connStr += 'Integrated Security=True;' }
 $conn = New-Object System.Data.SqlClient.SqlConnection $connStr
 try {
 $conn.Open()
 $cmd = $conn.CreateCommand()
 $cmd.CommandText = $Query
 $cmd.CommandTimeout = 300
 $adapter = New-Object System.Data.SqlClient.SqlDataAdapter $cmd
 $ds = New-Object System.Data.DataSet
 $adapter.Fill($ds) | Out-Null
 Write-SysLog "SQL OK : $Server/$Database | $($ds.Tables[0].Rows.Count) lignes"
 return $ds.Tables[0]
 } catch {
 Write-SysLog "Erreur SQL $Server/$Database : $_" -Level 'ERROR'
 throw
 } finally {
 $conn.Dispose()
 }
}

function Backup-SQLDatabase {
 param([string]$DatabaseName,[string]$Server=$SQLServer,[ValidateSet('FULL','DIFFERENTIAL','LOG')][string]$BackupType='FULL',[string]$BackupPath=$BackupRepository)
 $ts = Get-Date -f yyyyMMdd_HHmmss
 $ext = if($BackupType -eq 'LOG'){'trn'}else{'bak'}
 $file = Join-Path $BackupPath "${DatabaseName}_${BackupType}_${ts}.$ext"
 $sql = "BACKUP $($BackupType -eq 'LOG' ? 'LOG' : 'DATABASE') [$DatabaseName] TO DISK = N'$file' WITH COMPRESSION, STATS = 10, $($BackupType -eq 'DIFFERENTIAL' ? 'DIFFERENTIAL,' : '')FORMAT"
 Invoke-SQLQuery -Query $sql -Database 'master' -Server $Server
 Write-SysLog "Backup SQL $BackupType : $DatabaseName → $file"
 return $file
}

