function Invoke-RemoteCommand {
 param([string]$ScriptBlock,[string[]]$ComputerList,[PSCredential]$Credential=$null,[int]$ThrottleLimit=10)
 $sb = [ScriptBlock]::Create($ScriptBlock)
 $params = @{ ComputerName=$ComputerList; ScriptBlock=$sb; ThrottleLimit=$ThrottleLimit; ErrorAction='SilentlyContinue' }
 if ($Credential) { $params['Credential'] = $Credential }
 $jobs = Invoke-Command @params -AsJob
 $jobs | Wait-Job | Out-Null
 $results = foreach ($job in ($jobs | Get-Job)) {
 $out = $null; $err = $null
 try { $out = Receive-Job $job -ErrorAction Stop; $success=$true } catch { $err=$_.Exception.Message; $success=$false }
 [PSCustomObject]@{ Computer=$job.Location; Output=$out; Error=$err; Success=$success }
 }
 Write-SysLog "Commande distante : $($results.Where({$_.Success}).Count)/$($ComputerList.Count) OK"
 return $results
}

