function Invoke-CICDPipeline {
 param([string]$PipelineName,[string]$Branch='main',[hashtable]$Variables=@{})
 $headers = @{'Authorization'="Bearer $CI_CD_TOKEN";'Content-Type'='application/json'}
 $body = @{ definitionName=$PipelineName; sourceBranch=$Branch; variables=$Variables } | ConvertTo-Json -Depth 3
 try {
 $run = Invoke-RestMethod -Uri "$CICD_API_URL/pipelines/run" -Method Post -Headers $headers -Body $body -ErrorAction Stop
 Write-SysLog "Pipeline déclenché : $PipelineName ($($run.runId))"
 return [PSCustomObject]@{ RunId=$run.runId; Status=$run.state; Url=$run.url }
 } catch {
 Write-SysLog "Échec déclenchement pipeline : $_" -Level 'ERROR'
 throw
 }
}

function Build-DockerImageDSI {
 param([string]$ImageName,[string]$Tag='latest',[string]$DockerfilePath='./Dockerfile',[string]$RegistryUrl=$ContainerRegistry_URL)
 $full = "$RegistryUrl/$ImageName`:$Tag"
 try {
 docker build -t $full -f $DockerfilePath . | Out-Null
 docker push $full | Out-Null
 Write-SysLog "Image Docker pushée : $full"
 return $true
 } catch {
 Write-SysLog "Échec Docker build/push : $_" -Level 'ERROR'
 return $false
 }
}

function Deploy-K8sManifestDSI {
 param([string]$ManifestPath,[string]$Namespace='default',[string]$KubeConfig=$KubeConfig_Path)
 $env:KUBECONFIG = $KubeConfig
 try {
 kubectl apply -f $ManifestPath -n $Namespace
 $deploy = (kubectl get deployment -n $Namespace -o json | ConvertFrom-Json).items | Select-Object -First 1
 kubectl rollout status deployment/$($deploy.metadata.name) -n $Namespace --timeout=300s
 Write-SysLog "K8s déployé : $ManifestPath"
 return 'Completed'
 } catch {
 Write-SysLog "Échec K8s : $_" -Level 'ERROR'
 return 'Failed'
 }
}

function Apply-TerraformDSI {
 param([string]$Workspace,[string]$VarFile='terraform.tfvars',[switch]$AutoApprove)
 try {
 terraform workspace select $Workspace
 terraform init -input=false
 terraform plan -var-file=$VarFile -detailed-exitcode -out=tfplan
 if ($LASTEXITCODE -eq 0) { return [PSCustomObject]@{Action='NoChange';Status='OK'} }
 if ($AutoApprove) {
 terraform apply tfplan
 Write-SysLog "IaC appliqué : workspace $Workspace"
 } else {
 Write-SysLog "Plan Terraform prêt sur $Workspace (validation manuelle requise)" -Level 'WARN'
 }
 return [PSCustomObject]@{Action='Applied';Status='OK';Workspace=$Workspace}
 } catch {
 Write-SysLog "Échec Terraform : $_" -Level 'ERROR'
 throw
 }
}

function Invoke-ModelTrainingDSI {
 param([string]$ScriptPath,[string]$DatasetUri,[string]$ComputeTarget='gpu-cluster',[hashtable]$HyperParams=@{})
 try {
 $run = Submit-MLJob -Script $ScriptPath -Data $DatasetUri -Compute $ComputeTarget -Params $HyperParams
 while ($run.Status -notin 'Completed','Failed') { Start-Sleep 15; $run = Get-MLJob $run.RunId }
 Write-SysLog "Entraînement ML : $($run.RunId) | $($run.Status)"
 return $run
 } catch {
 Write-SysLog "Échec entraînement ML : $_" -Level 'ERROR'
 throw
 }
}

function Get-ModelDriftMetricsDSI {
 param([string]$EndpointUrl,[string]$BaselineDataset,[double]$Threshold=$DriftThreshold)
 try {
 $live = Invoke-RestMethod "$EndpointUrl/sampling"
 $drift = Calculate-PSI -Target $live -Reference $BaselineDataset
 $alert = $drift -gt $Threshold
 if ($alert) { Send-AlertMail -To $AdminEmail -Subject "⚠️ Drift ML détecté" -Body "PSI=$drift (seuil=$Threshold) sur $EndpointUrl" }
 Write-SysLog "Drift ML : PSI=$drift Seuil=$Threshold Alerte=$alert"
 return [PSCustomObject]@{PSI=$drift;Threshold=$Threshold;DriftDetected=$alert;Timestamp=(Get-Date)}
 } catch {
 Write-SysLog "Erreur drift ML : $_" -Level 'ERROR'
 throw
 }
}

public static string ReadFileContent(string filePath, string encoding = "UTF8") {
