public static void WriteLog(string message, string level = "INFO", string logPath = @"C:\Logs\DSI\app.log") {
 string entry = $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] [{level}] {message}";
 Console.WriteLine(entry);
 string dir = Path.GetDirectoryName(logPath);
 if (!Directory.Exists(dir)) Directory.CreateDirectory(dir);
 File.AppendAllText(logPath, entry + Environment.NewLine, Encoding.UTF8);
}

public static void WriteAllLines(string filePath, string[] lines, bool append = false) {
 string dir = Path.GetDirectoryName(filePath);
 if (!string.IsNullOrEmpty(dir) && !Directory.Exists(dir))
 Directory.CreateDirectory(dir);
 if (append)
 File.AppendAllLines(filePath, lines, Encoding.UTF8);
 else
 File.WriteAllLines(filePath, lines, Encoding.UTF8);
}

public static bool CopyFileWithRetry(string source, string destination, int maxRetries = 3, int delayMs = 2000) {
 string destDir = Path.GetDirectoryName(destination);
 if (!string.IsNullOrEmpty(destDir) && !Directory.Exists(destDir))
 Directory.CreateDirectory(destDir);
 for (int i = 0; i < maxRetries; i++) {
 try {
 File.Copy(source, destination, overwrite: true);
 return true;
 } catch (Exception ex) {
 WriteLog($"Copie échouée tentative {i+1}/{maxRetries} : {ex.Message}", "WARN");
 if (i < maxRetries - 1) Thread.Sleep(delayMs);
 }
 }
 WriteLog($"Copie définitivement échouée : {source} → {destination}", "ERROR");
 return false;
}

public static int ArchiveOldFiles(string sourceDir, string archivePath, int olderThanDays = 30) {
 var cutoff = DateTime.Now.AddDays(-olderThanDays);
 var files = Directory.GetFiles(sourceDir)
 .Where(f => File.GetLastWriteTime(f) < cutoff)
 .ToList();
 if (!files.Any()) return 0;
 using (var zip = ZipFile.Open(archivePath, ZipArchiveMode.Create)) {
 foreach (var f in files) {
 zip.CreateEntryFromFile(f, Path.GetFileName(f), CompressionLevel.Optimal);
 }
 }
 WriteLog($"{files.Count} fichiers archivés dans {archivePath}");
 return files.Count;
}

public static List<Dictionary<string, string>> QueryActiveDirectory(string ldapFilter, string[] properties = null, string searchBase = "DC=corp,DC=local") {
 properties ??= new[] { "samAccountName", "displayName", "mail", "department" };
 var results = new List<Dictionary<string, string>>();
 using var entry = new DirectoryEntry($"LDAP://{searchBase}");
 using var searcher = new DirectorySearcher(entry, ldapFilter, properties);
 searcher.PageSize = 1000;
 using var all = searcher.FindAll();
 foreach (SearchResult sr in all) {
 var dict = new Dictionary<string, string>();
 foreach (var prop in properties) {
 dict[prop] = sr.Properties.Contains(prop) && sr.Properties[prop].Count > 0
 ? sr.Properties[prop][0]?.ToString() ?? ""
 : "";
 }
 results.Add(dict);
 }
 return results;
}

