public static List<string> GetUserGroupMemberships(string samAccountName, string domain = "corp.local") {
 var groups = new List<string>();
 try {
 using var ctx = new PrincipalContext(ContextType.Domain, domain);
 using var user = UserPrincipal.FindByIdentity(ctx, IdentityType.SamAccountName, samAccountName);
 if (user == null) throw new Exception($"Utilisateur introuvable : {samAccountName}");
 using var authGroups = user.GetAuthorizationGroups();
 foreach (var g in authGroups) {
 groups.Add(g.SamAccountName);
 g.Dispose();
 }
 } catch (Exception ex) {
 WriteLog($"Erreur groupes AD {samAccountName} : {ex.Message}", "ERROR");
 }
 return groups;
}

public static bool IsUserInGroup(string samAccountName, string groupName, string domain = "corp.local") {
 try {
 using var ctx = new PrincipalContext(ContextType.Domain, domain);
 using var group = GroupPrincipal.FindByIdentity(ctx, groupName);
 if (group == null) return false;
 return group.GetMembers(recursive: true).Any(m => m.SamAccountName?.Equals(samAccountName, StringComparison.OrdinalIgnoreCase) == true);
 } catch {
 return false;
 }
}

