public static int BulkInsertSql(DataTable data, string tableName, string connectionString = "Server=SQL01.corp.local;Integrated Security=True;", int batchSize = 1000) {
 using var conn = new SqlConnection(connectionString);
 conn.Open();
 using var bulk = new SqlBulkCopy(conn) {
 DestinationTableName = tableName,
 BatchSize = batchSize,
 BulkCopyTimeout = 600
 };
 foreach (DataColumn col in data.Columns)
 bulk.ColumnMappings.Add(col.ColumnName, col.ColumnName);
 bulk.WriteToServer(data);
 WriteLog($"Bulk insert : {data.Rows.Count} lignes → {tableName}");
 return data.Rows.Count;
}

public static async Task<string> SendHttpRequest(string url, string method = "GET", string body = null, string bearerToken = null, int timeoutSeconds = 30) {
 using var client = new HttpClient { Timeout = TimeSpan.FromSeconds(timeoutSeconds) };
 if (bearerToken != null)
 client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", bearerToken);
 HttpResponseMessage response;
 switch (method.ToUpper()) {
 case "POST":
 var postContent = new StringContent(body ?? "{}", Encoding.UTF8, "application/json");
 response = await client.PostAsync(url, postContent);
 break;
 case "PUT":
 var putContent = new StringContent(body ?? "{}", Encoding.UTF8, "application/json");
 response = await client.PutAsync(url, putContent);
 break;
 case "DELETE":
 response = await client.DeleteAsync(url);
 break;
 default:
 response = await client.GetAsync(url);
 break;
 }
 response.EnsureSuccessStatusCode();
 return await response.Content.ReadAsStringAsync();
}

