public static string HashPassword(string password, int iterations = 100000) {
 byte[] salt = new byte[32];
 using var rng = RandomNumberGenerator.Create();
 rng.GetBytes(salt);
 using var pbkdf2 = new Rfc2898DeriveBytes(password, salt, iterations, HashAlgorithmName.SHA256);
 byte[] hash = pbkdf2.GetBytes(32);
 byte[] combined = new byte[salt.Length + hash.Length + 4];
 BitConverter.GetBytes(iterations).CopyTo(combined, 0);
 salt.CopyTo(combined, 4);
 hash.CopyTo(combined, 36);
 return Convert.ToBase64String(combined);
}

public static bool VerifyPassword(string password, string storedHash) {
 try {
 byte[] combined = Convert.FromBase64String(storedHash);
 int iterations = BitConverter.ToInt32(combined, 0);
 byte[] salt = combined.Skip(4).Take(32).ToArray();
 byte[] originalHash = combined.Skip(36).ToArray();
 using var pbkdf2 = new Rfc2898DeriveBytes(password, salt, iterations, HashAlgorithmName.SHA256);
 byte[] testHash = pbkdf2.GetBytes(32);
 return originalHash.SequenceEqual(testHash);
 } catch {
 return false;
 }
}

public static string EncryptString(string plainText, string key, string iv = null) {
 using var aes = Aes.Create();
 aes.Key = SHA256.HashData(Encoding.UTF8.GetBytes(key));
 if (iv != null)
 aes.IV = Convert.FromBase64String(iv);
 else
 aes.GenerateIV();
 using var encryptor = aes.CreateEncryptor();
 using var ms = new MemoryStream();
 ms.Write(aes.IV, 0, aes.IV.Length); // Préfixe IV
 using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
 using (var sw = new StreamWriter(cs))
 sw.Write(plainText);
 return Convert.ToBase64String(ms.ToArray());
}

public static string DecryptString(string cipherText, string key) {
 byte[] data = Convert.FromBase64String(cipherText);
 using var aes = Aes.Create();
 aes.Key = SHA256.HashData(Encoding.UTF8.GetBytes(key));
 byte[] iv = data.Take(16).ToArray();
 aes.IV = iv;
 using var decryptor = aes.CreateDecryptor();
 using var ms = new MemoryStream(data.Skip(16).ToArray());
 using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);
 using var sr = new StreamReader(cs);
 return sr.ReadToEnd();
}

public static string GenerateSecureToken(int length = 32, string format = "Base64") {
 byte[] bytes = new byte[length];
 using var rng = RandomNumberGenerator.Create();
 rng.GetBytes(bytes);
 return format.ToLower() switch {
 "hex" => Convert.ToHexString(bytes).ToLower(),
 "alphanumeric" => new string(Convert.ToBase64String(bytes).Where(char.IsLetterOrDigit).Take(length).ToArray()),
 _ => Convert.ToBase64String(bytes)
 };
}

public static string SanitizeInput(string input, string sanitizeType = "All") {
 if (string.IsNullOrEmpty(input)) return input;
 string result = input;
 bool all = sanitizeType.Equals("All", StringComparison.OrdinalIgnoreCase);
 if (all || sanitizeType.Equals("Html", StringComparison.OrdinalIgnoreCase))
 result = WebUtility.HtmlEncode(result);
 if (all || sanitizeType.Equals("Sql", StringComparison.OrdinalIgnoreCase))
 result = result.Replace("'", "''").Replace(";", "").Replace("--", "").Replace("/*", "").Replace("*/", "");
 if (all || sanitizeType.Equals("Ldap", StringComparison.OrdinalIgnoreCase))
 result = result.Replace("*", "\\2a").Replace("(", "\\28").Replace(")", "\\29").Replace("\\", "\\5c").Replace("\0", "\\00");
 if (all || sanitizeType.Equals("Path", StringComparison.OrdinalIgnoreCase))
 result = string.Concat(result.Split(Path.GetInvalidFileNameChars()));
 return result;
}

