public static Dictionary<string, string> RunProcessCapture(string executable, string arguments = "", string workingDir = null, int timeoutMs = 30000) {
 var psi = new ProcessStartInfo {
 FileName = executable, Arguments = arguments,
 RedirectStandardOutput = true, RedirectStandardError = true,
 UseShellExecute = false, CreateNoWindow = true
 };
 if (workingDir != null) psi.WorkingDirectory = workingDir;
 using var proc = Process.Start(psi);
 string stdout = proc.StandardOutput.ReadToEnd();
 string stderr = proc.StandardError.ReadToEnd();
 bool timedOut = !proc.WaitForExit(timeoutMs);
 if (timedOut) proc.Kill(true);
 return new Dictionary<string, string> {
 ["ExitCode"] = timedOut ? "-1" : proc.ExitCode.ToString(),
 ["Stdout"] = stdout, ["Stderr"] = stderr,
 ["TimedOut"] = timedOut.ToString()
 };
}

