}

public static async Task RetryAction(Func<Task> action, int maxAttempts = 3, int initialDelayMs = 1000) {
 Exception lastEx = null;
 for (int attempt = 1; attempt <= maxAttempts; attempt++) {
 try {
 await action();
 return;
 } catch (Exception ex) {
 lastEx = ex;
 WriteLog($"Tentative {attempt}/{maxAttempts} échouée : {ex.Message}", "WARN");
 if (attempt < maxAttempts)
 await Task.Delay(initialDelayMs * (int)Math.Pow(2, attempt - 1));
 }
 }
 WriteLog($"Toutes les tentatives ont échoué : {lastEx?.Message}", "ERROR");
 throw lastEx!;
}

public static DataTable ParseCsvToDataTable(string csvPath, char delimiter = ',', bool hasHeader = true) {
 var dt = new DataTable();
 using var reader = new StreamReader(csvPath, Encoding.UTF8);
 string firstLine = reader.ReadLine();
 if (firstLine == null) return dt;
 string[] headers = firstLine.Split(delimiter);
 if (hasHeader)
 foreach (var h in headers) dt.Columns.Add(h.Trim('"').Trim());
 else {
 for (int i = 0; i < headers.Length; i++) dt.Columns.Add($"Column{i}");
 dt.Rows.Add(headers.Select(v => (object)v.Trim('"').Trim()).ToArray());
 }
 while (!reader.EndOfStream) {
 string line = reader.ReadLine();
 if (string.IsNullOrWhiteSpace(line)) continue;
 string[] values = line.Split(delimiter);
 dt.Rows.Add(values.Select(v => (object)v.Trim('"').Trim()).ToArray());
 }
 WriteLog($"CSV parsé : {csvPath} | {dt.Rows.Count} lignes");
 return dt;
}

