 ?? throw new JsonException("Désérialisation retourne null");
}

public static List<Dictionary<string, string>> GetWindowsEventLogs(string logName = "System", string entryType = "Error", int last = 50, string machineName = ".") {
 var results = new List<Dictionary<string, string>>();
 using var log = new EventLog(logName, machineName);
 var targetType = Enum.TryParse<EventLogEntryType>(entryType, out var et) ? et : EventLogEntryType.Error;
 var entries = log.Entries.Cast<EventLogEntry>()
 .Where(e => e.EntryType == targetType)
 .OrderByDescending(e => e.TimeGenerated)
 .Take(last);
 foreach (var e in entries) {
 results.Add(new Dictionary<string, string> {
 ["Time"] = e.TimeGenerated.ToString("o"),
 ["Source"] = e.Source,
 ["EventId"] = e.EventID.ToString(),
 ["Message"] = e.Message.Length > 500 ? e.Message[..500] + "..." : e.Message
 });
 }
 return results;
}

public static Dictionary<string, string> ValidateIPAddress(string ipAddress) {
 bool isValid = IPAddress.TryParse(ipAddress, out var ip);
 if (!isValid)
 return new Dictionary<string, string> { ["IsValid"] = "false" };
 bool isPrivate = ip.AddressFamily == System.Net.Sockets.AddressFamily.InterNetwork && (
 IPNetwork.Parse("10.0.0.0/8").Contains(ip) ||
 IPNetwork.Parse("172.16.0.0/12").Contains(ip) ||
 IPNetwork.Parse("192.168.0.0/16").Contains(ip));
 return new Dictionary<string, string> {
 ["IsValid"] = "true",
 ["Version"] = ip.AddressFamily.ToString(),
 ["IsPrivate"] = isPrivate.ToString(),
 ["IsLoopback"] = IPAddress.IsLoopback(ip).ToString(),
 ["IsIPv6"] = (ip.AddressFamily == System.Net.Sockets.AddressFamily.InterNetworkV6).ToString()
 };
}

