public static Dictionary<string, string> MonitorServiceHealth(string serviceName, bool autoRestart = true, string machineName = ".") {
 try {
 using var svc = new ServiceController(serviceName, machineName);
 bool wasDown = svc.Status != ServiceControllerStatus.Running;
 bool restarted = false;
 if (wasDown && autoRestart) {
 svc.Start();
 svc.WaitForStatus(ServiceControllerStatus.Running, TimeSpan.FromSeconds(30));
 restarted = true;
 WriteLog($"Service {serviceName} redémarré automatiquement", "WARN");
 }
 return new Dictionary<string, string> {
 ["Name"] = serviceName,
 ["Status"] = svc.Status.ToString(),
 ["Restarted"] = restarted.ToString(),
 ["Error"] = ""
 };
 } catch (Exception ex) {
 WriteLog($"Erreur surveillance service {serviceName} : {ex.Message}", "ERROR");
 return new Dictionary<string, string> { ["Name"] = serviceName, ["Status"] = "ERREUR", ["Error"] = ex.Message };
 }
}

public static object GetRegistryValue(string keyPath, string valueName, string hive = "HKLM", bool use64bit = true) {
 var view = use64bit ? RegistryView.Registry64 : RegistryView.Registry32;
 using var rootKey = hive.ToUpper() switch {
 "HKCU" => RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, view),
 "HKCR" => RegistryKey.OpenBaseKey(RegistryHive.ClassesRoot, view),
 _ => RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, view)
 };
 using var key = rootKey.OpenSubKey(keyPath);
 return key?.GetValue(valueName);
}

public static void SetRegistryValue(string keyPath, string valueName, object value, string valueKind = "String", string hive = "HKLM") {
 using var rootKey = hive.ToUpper() == "HKCU"
 ? RegistryKey.OpenBaseKey(RegistryHive.CurrentUser, RegistryView.Registry64)
 : RegistryKey.OpenBaseKey(RegistryHive.LocalMachine, RegistryView.Registry64);
 using var key = rootKey.CreateSubKey(keyPath, writable: true)
