public static Dictionary<string, string> PingHost(string host, int count = 4, int timeoutMs = 1000) {
 using var ping = new Ping();
 var times = new List<long>();
 int failures = 0;
 for (int i = 0; i < count; i++) {
 try {
 var reply = ping.Send(host, timeoutMs);
 if (reply.Status == IPStatus.Success) times.Add(reply.RoundtripTime);
 else failures++;
 } catch { failures++; }
 }
 bool success = times.Count > 0;
 return new Dictionary<string, string> {
 ["Host"] = host, ["Success"] = success.ToString(),
 ["MinMs"] = success ? times.Min().ToString() : "-1",
 ["MaxMs"] = success ? times.Max().ToString() : "-1",
 ["AvgMs"] = success ? times.Average().ToString("F0") : "-1",
 ["PacketLoss"] = $"{(failures * 100.0 / count):F0}%"
 };
}

