private static void FlattenJson(JsonElement elem, string prefix, Dictionary<string, string> result) {
 switch (elem.ValueKind) {
 case JsonValueKind.Object:
 foreach (var p in elem.EnumerateObject())
 FlattenJson(p.Value, string.IsNullOrEmpty(prefix) ? p.Name : $"{prefix}:{p.Name}", result);
 break;
 case JsonValueKind.Array:
 int i = 0;
 foreach (var item in elem.EnumerateArray())
 FlattenJson(item, $"{prefix}[{i++}]", result);
 break;
 default:
 result[prefix] = elem.ToString();
 break;
 }
}

