 var targetKeys = target.AsEnumerable().ToDictionary(r => r[keyColumn].ToString());
 foreach (var kv in targetKeys)
 if (!sourceKeys.ContainsKey(kv.Key))
 added.ImportRow(kv.Value);
 foreach (var kv in sourceKeys) {
 if (!targetKeys.ContainsKey(kv.Key)) { removed.ImportRow(kv.Value); continue; }
 var srcRow = kv.Value;
 var tgtRow = targetKeys[kv.Key];
 bool diff = source.Columns.Cast<DataColumn>().Any(c => srcRow[c.ColumnName]?.ToString() != tgtRow[c.ColumnName]?.ToString());
 if (diff) modified.ImportRow(tgtRow);
 }
 return new Dictionary<string, DataTable> { ["Added"] = added, ["Removed"] = removed, ["Modified"] = modified };
}

