 foreach (var item in items) {
 batch.Add(item);
 if (batch.Count >= batchSize) {
 batchNum++;
 processor(batch);
 total += batch.Count;
 WriteLog($"Lot {batchNum} traité : {batch.Count} éléments (total: {total})", "DEBUG");
 batch.Clear();
 if (delayBetweenBatchesMs > 0) Thread.Sleep(delayBetweenBatchesMs);
 }
 }
 if (batch.Count > 0) { processor(batch); total += batch.Count; }
 WriteLog($"Traitement par lots terminé : {total} éléments en {batchNum + (batch.Count > 0 ? 1 : 0)} lots");
 return total;
}

