public static double CalculatePSI(double[] actual, double[] expected, int bins = 10) {
 if (actual.Length == 0 || expected.Length == 0) return double.NaN;
 double min = Math.Min(actual.Min(), expected.Min());
 double max = Math.Max(actual.Max(), expected.Max()) + 1e-9;
 double binWidth = (max - min) / bins;
 var actualBins = new double[bins];
 var expectedBins = new double[bins];
 foreach (var v in actual) {
 int b = (int)Math.Min((v - min) / binWidth, bins - 1);
 actualBins[b]++;
 }
 foreach (var v in expected) {
 int b = (int)Math.Min((v - min) / binWidth, bins - 1);
 expectedBins[b]++;
 }
 double psi = 0;
 for (int i = 0; i < bins; i++) {
 double a = Math.Max(actualBins[i] / actual.Length, 1e-9);
 double e = Math.Max(expectedBins[i] / expected.Length, 1e-9);
 psi += (a - e) * Math.Log(a / e);
 }
 return Math.Round(psi, 6);
}

